#!/usr/bin/env node
/**
 * fix-smallvec.js
 *
 * Fixes SmallVec serialization in solita-generated files.
 *
 * Problem: Rust SmallVec<u8, T> uses a 1-byte length prefix, SmallVec<u16, T> uses 2 bytes.
 *          Solita generates beet.array() which always uses 4 bytes.
 *
 * Usage: Run automatically via `yarn generate` or manually with `node scripts/fix-smallvec.js`
 *
 * Adding new SmallVec types:
 *   1. If the Rust type ALWAYS uses SmallVec (never Vec), add the beet type to SMALLVEC_U8_BEET_TYPES_GLOBAL
 *      Example: CompiledInstructionConstraint is only ever used with SmallVec, so add 'compiledInstructionConstraintBeet'
 *
 *   2. If the Rust type uses SmallVec in some structs but Vec in others, add to SMALLVEC_U8_BEET_TYPES_FILE_SPECIFIC
 *      Example: DataConstraint uses Vec in InstructionConstraint (legacy) but SmallVec in CompiledInstructionConstraint,
 *               so we list only the files where it should be SmallVec
 *
 *   3. For SmallVec<u8, u8> or SmallVec<u16, u8> fields (byte arrays), add file-specific handling below
 */

const fs = require('fs');
const path = require('path');

const GENERATED_DIR = path.join(__dirname, '..', 'src', 'generated', 'types');
const SIGNER_WRAPPER_FILE = 'SmartAccountSignerWrapper.ts';

// Beet types that ALWAYS use SmallVec<u8, X> (never Vec)
const SMALLVEC_U8_BEET_TYPES_GLOBAL = [
  'compiledInstructionConstraintBeet',
  'compiledAccountConstraintBeet',
  'compiledLimitedSpendingLimitBeet',
  'compiledInstructionBeet',
  'messageAddressTableLookupBeet',
];

// Beet types that use SmallVec only in specific files (Vec elsewhere)
const SMALLVEC_U8_BEET_TYPES_FILE_SPECIFIC = {
  'dataConstraintBeet': [
    'CompiledInstructionConstraint.ts',
    'CompiledAccountConstraintType.ts',
  ],
  'beetSolana.publicKey': [
    'TransactionMessage.ts',
    'ProgramInteractionPolicyCreationPayload.ts',
  ],
};

function processFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return false;
  }

  let content = fs.readFileSync(filePath, 'utf8');
  const originalContent = content;
  const fileName = path.basename(filePath);

  if (fileName === SIGNER_WRAPPER_FILE) {
    content = `/**
 * This code was GENERATED using the solita package.
 * Please DO NOT EDIT THIS FILE, instead rerun solita to update it or write a wrapper to add functionality.
 *
 * See: https://github.com/metaplex-foundation/solita
 */

import * as beet from '@metaplex-foundation/beet'
import * as web3 from '@solana/web3.js'
import {
  LegacySmartAccountSigner,
  legacySmartAccountSignerBeet,
} from './LegacySmartAccountSigner'
import { SmartAccountSigner } from './SmartAccountSigner'

export type SmartAccountSignerWrapperRecord = {
  V1: { fields: [LegacySmartAccountSigner[]] }
  V2: { fields: [SmartAccountSigner[]] }
}

export type SmartAccountSignerWrapper =
  beet.DataEnumKeyAsKind<SmartAccountSignerWrapperRecord>

export const isSmartAccountSignerWrapperV1 = (
  x: SmartAccountSignerWrapper
): x is SmartAccountSignerWrapper & { __kind: 'V1' } => x.__kind === 'V1'
export const isSmartAccountSignerWrapperV2 = (
  x: SmartAccountSignerWrapper
): x is SmartAccountSignerWrapper & { __kind: 'V2' } => x.__kind === 'V2'

const SIGNERS_VERSION_V1 = 0x00
const SIGNERS_VERSION_V2 = 0x01
const ENTRY_HEADER_LEN = 4

type PackedSigner = { tag: number; payload: Uint8Array }

const toBigInt = (value: beet.bignum): bigint => BigInt(value.toString())

const readU16LE = (buf: Buffer, offset: number) =>
  buf[offset] | (buf[offset + 1] << 8)

const readU64LE = (buf: Buffer, offset: number) => beet.u64.read(buf, offset)

const writeU64LE = (buf: Buffer, offset: number, value: beet.bignum) => {
  beet.u64.write(buf, offset, toBigInt(value))
}

const readLength = (buf: Buffer, offset: number) => {
  const count =
    buf[offset] | (buf[offset + 1] << 8) | (buf[offset + 2] << 16)
  const version = buf[offset + 3]
  return { count, version }
}

const writeLength = (
  buf: Buffer,
  offset: number,
  count: number,
  version: number
) => {
  buf[offset] = count & 0xff
  buf[offset + 1] = (count >> 8) & 0xff
  buf[offset + 2] = (count >> 16) & 0xff
  buf[offset + 3] = version & 0xff
}

const pubkeyFrom = (payload: Uint8Array, start: number) =>
  new web3.PublicKey(payload.slice(start, start + 32))

const pubkeyToBytes = (key: web3.PublicKey) => key.toBytes()

const u64ToBytes = (value: beet.bignum) => {
  const buf = Buffer.alloc(8)
  writeU64LE(buf, 0, value)
  return buf
}

const packSigner = (signer: SmartAccountSigner): PackedSigner => {
  switch (signer.__kind) {
    case 'Native': {
      const payload = Buffer.concat([
        Buffer.from(pubkeyToBytes(signer.key)),
        Buffer.from([signer.permissions.mask]),
      ])
      return { tag: 0, payload }
    }
    case 'P256Webauthn': {
      const payload = Buffer.concat([
        Buffer.from(pubkeyToBytes(signer.keyId)),
        Buffer.from([signer.permissions.mask]),
        Buffer.from(signer.data.compressedPubkey),
        Buffer.from([signer.data.rpIdLen]),
        Buffer.from(signer.data.rpId),
        Buffer.from(signer.data.rpIdHash),
        u64ToBytes(signer.data.counter),
        Buffer.from(pubkeyToBytes(signer.data.sessionKeyData.key)),
        u64ToBytes(signer.data.sessionKeyData.expiration),
      ])
      return { tag: 1, payload }
    }
    case 'Secp256k1': {
      const payload = Buffer.concat([
        Buffer.from(pubkeyToBytes(signer.keyId)),
        Buffer.from([signer.permissions.mask]),
        Buffer.from(signer.data.uncompressedPubkey),
        Buffer.from(signer.data.ethAddress),
        Buffer.from([signer.data.hasEthAddress ? 1 : 0]),
        Buffer.from(pubkeyToBytes(signer.data.sessionKeyData.key)),
        u64ToBytes(signer.data.sessionKeyData.expiration),
      ])
      return { tag: 2, payload }
    }
    case 'Ed25519External': {
      const payload = Buffer.concat([
        Buffer.from(pubkeyToBytes(signer.keyId)),
        Buffer.from([signer.permissions.mask]),
        Buffer.from(signer.data.externalPubkey),
        Buffer.from(pubkeyToBytes(signer.data.sessionKeyData.key)),
        u64ToBytes(signer.data.sessionKeyData.expiration),
      ])
      return { tag: 3, payload }
    }
    default:
      throw new Error('Unsupported signer variant')
  }
}

const parseSigner = (tag: number, payload: Uint8Array): SmartAccountSigner => {
  switch (tag) {
    case 0: {
      const key = pubkeyFrom(payload, 0)
      const permissions = { mask: payload[32] }
      return { __kind: 'Native', key, permissions }
    }
    case 1: {
      const keyId = pubkeyFrom(payload, 0)
      const permissions = { mask: payload[32] }
      const compressedPubkey = Array.from(payload.slice(33, 66))
      const rpIdLen = payload[66]
      const rpId = Array.from(payload.slice(67, 99))
      const rpIdHash = Array.from(payload.slice(99, 131))
      const counter = readU64LE(Buffer.from(payload), 131)
      const sessionKey = pubkeyFrom(payload, 139)
      const sessionKeyExpiration = readU64LE(Buffer.from(payload), 171)
      return {
        __kind: 'P256Webauthn',
        keyId,
        permissions,
        data: {
          compressedPubkey,
          rpIdLen,
          rpId,
          rpIdHash,
          counter,
          sessionKeyData: {
            key: sessionKey,
            expiration: sessionKeyExpiration,
          },
        },
      }
    }
    case 2: {
      const keyId = pubkeyFrom(payload, 0)
      const permissions = { mask: payload[32] }
      const uncompressedPubkey = Array.from(payload.slice(33, 97))
      const ethAddress = Array.from(payload.slice(97, 117))
      const hasEthAddress = payload[117] !== 0
      const sessionKey = pubkeyFrom(payload, 118)
      const sessionKeyExpiration = readU64LE(Buffer.from(payload), 150)
      return {
        __kind: 'Secp256k1',
        keyId,
        permissions,
        data: {
          uncompressedPubkey,
          ethAddress,
          hasEthAddress,
          sessionKeyData: {
            key: sessionKey,
            expiration: sessionKeyExpiration,
          },
        },
      }
    }
    case 3: {
      const keyId = pubkeyFrom(payload, 0)
      const permissions = { mask: payload[32] }
      const externalPubkey = Array.from(payload.slice(33, 65))
      const sessionKey = pubkeyFrom(payload, 65)
      const sessionKeyExpiration = readU64LE(Buffer.from(payload), 97)
      return {
        __kind: 'Ed25519External',
        keyId,
        permissions,
        data: {
          externalPubkey,
          sessionKeyData: {
            key: sessionKey,
            expiration: sessionKeyExpiration,
          },
        },
      }
    }
    default:
      throw new Error('Invalid signer type')
  }
}

const readWrapper = (buf: Buffer, offset: number): SmartAccountSignerWrapper => {
  const { count, version } = readLength(buf, offset)
  let cursor = offset + 4

  if (version === SIGNERS_VERSION_V1) {
    const signers: LegacySmartAccountSigner[] = []
    for (let i = 0; i < count; i++) {
      const signer = legacySmartAccountSignerBeet.read(buf, cursor)
      signers.push(signer)
      cursor += legacySmartAccountSignerBeet.byteSize
    }
    return { __kind: 'V1', fields: [signers] }
  }

  if (version === SIGNERS_VERSION_V2) {
    const signers: SmartAccountSigner[] = []
    for (let i = 0; i < count; i++) {
      const tag = buf[cursor]
      const payloadLen = readU16LE(buf, cursor + 1)
      const payload = buf.slice(cursor + ENTRY_HEADER_LEN, cursor + ENTRY_HEADER_LEN + payloadLen)
      signers.push(parseSigner(tag, payload))
      cursor += ENTRY_HEADER_LEN + payloadLen
    }
    return { __kind: 'V2', fields: [signers] }
  }

  throw new Error('Unsupported signer version')
}

const writeWrapper = (
  buf: Buffer,
  offset: number,
  value: SmartAccountSignerWrapper
) => {
  if (value.__kind === 'V1') {
    const signers = value.fields[0]
    writeLength(buf, offset, signers.length, SIGNERS_VERSION_V1)
    let cursor = offset + 4
    for (const signer of signers) {
      legacySmartAccountSignerBeet.write(buf, cursor, signer)
      cursor += legacySmartAccountSignerBeet.byteSize
    }
    return
  }

  if (value.__kind === 'V2') {
    const signers = value.fields[0]
    const packed = signers.map(packSigner)
    writeLength(buf, offset, packed.length, SIGNERS_VERSION_V2)
    let cursor = offset + 4
    for (const entry of packed) {
      buf[cursor] = entry.tag
      buf.writeUInt16LE(entry.payload.length, cursor + 1)
      buf[cursor + 3] = 0
      Buffer.from(entry.payload).copy(buf, cursor + ENTRY_HEADER_LEN)
      cursor += ENTRY_HEADER_LEN + entry.payload.length
    }
    return
  }

  throw new Error('Unsupported signer wrapper variant')
}

const makeFixedBeet = (byteSize: number) => ({
  read: (buf: Buffer, offset: number) => readWrapper(buf, offset),
  write: (buf: Buffer, offset: number, value: SmartAccountSignerWrapper) =>
    writeWrapper(buf, offset, value),
  byteSize,
  description: 'SmartAccountSignerWrapper',
})

export const smartAccountSignerWrapperBeet: beet.FixableBeet<
  SmartAccountSignerWrapper,
  SmartAccountSignerWrapper
> = {
  toFixedFromData: (buf: Buffer, offset: number) => {
    const { count, version } = readLength(buf, offset)
    if (version === SIGNERS_VERSION_V1) {
      return makeFixedBeet(4 + count * legacySmartAccountSignerBeet.byteSize)
    }
    if (version === SIGNERS_VERSION_V2) {
      let cursor = offset + 4
      for (let i = 0; i < count; i++) {
        const payloadLen = readU16LE(buf, cursor + 1)
        cursor += ENTRY_HEADER_LEN + payloadLen
      }
      return makeFixedBeet(cursor - offset)
    }
    throw new Error('Unsupported signer version')
  },
  toFixedFromValue: (value: SmartAccountSignerWrapper) => {
    if (value.__kind === 'V1') {
      const signers = value.fields[0]
      return makeFixedBeet(4 + signers.length * legacySmartAccountSignerBeet.byteSize)
    }
    if (value.__kind === 'V2') {
      const signers = value.fields[0]
      const total = signers.reduce((sum, signer) => {
        const packed = packSigner(signer)
        return sum + ENTRY_HEADER_LEN + packed.payload.length
      }, 4)
      return makeFixedBeet(total)
    }
    throw new Error('Unsupported signer wrapper variant')
  },
  description: 'SmartAccountSignerWrapper',
}
`
    if (content !== originalContent) {
      fs.writeFileSync(filePath, content);
      console.log('Fixed SmartAccountSignerWrapper serialization');
      return true;
    }
    return false;
  }

  // Global replacements
  for (const beetType of SMALLVEC_U8_BEET_TYPES_GLOBAL) {
    const regex = new RegExp(`beet\\.array\\(${beetType.replace('.', '\\.')}\\)`, 'g');
    content = content.replace(regex, `smallArray(beet.u8, ${beetType})`);
  }

  // File-specific replacements
  for (const [beetType, files] of Object.entries(SMALLVEC_U8_BEET_TYPES_FILE_SPECIFIC)) {
    if (files.includes(fileName)) {
      const regex = new RegExp(`beet\\.array\\(${beetType.replace('.', '\\.')}\\)`, 'g');
      content = content.replace(regex, `smallArray(beet.u8, ${beetType})`);
    }
  }

  // File-specific fixes for byte array fields (SmallVec<u8/u16, u8> -> beet.bytes in IDL)
  if (fileName === 'CompiledInstruction.ts') {
    // accountIndexes: SmallVec<u8, u8>
    content = content.replace(/\['accountIndexes', beet\.bytes\]/g, "['accountIndexes', smallArray(beet.u8, beet.u8)]");
    // data: SmallVec<u16, u8> (note: u16 length prefix)
    content = content.replace(/\['data', beet\.bytes\]/g, "['data', smallArray(beet.u16, beet.u8)]");
    content = content.replace(/accountIndexes: Uint8Array/g, 'accountIndexes: number[]');
    content = content.replace(/data: Uint8Array/g, 'data: number[]');
  }

  if (fileName === 'MessageAddressTableLookup.ts') {
    content = content.replace(/\['writableIndexes', beet\.bytes\]/g, "['writableIndexes', smallArray(beet.u8, beet.u8)]");
    content = content.replace(/\['readonlyIndexes', beet\.bytes\]/g, "['readonlyIndexes', smallArray(beet.u8, beet.u8)]");
    content = content.replace(/writableIndexes: Uint8Array/g, 'writableIndexes: number[]');
    content = content.replace(/readonlyIndexes: Uint8Array/g, 'readonlyIndexes: number[]');
  }

  if (fileName === 'CompiledHook.ts') {
    // instruction_data: SmallVec<u16, u8> (note: u16 length prefix)
    content = content.replace(/\['instructionData', beet\.bytes\]/g, "['instructionData', smallArray(beet.u16, beet.u8)]");
    content = content.replace(/instructionData: Uint8Array/g, 'instructionData: number[]');
  }

  if (fileName === 'CompiledAccountConstraintType.ts') {
    // Pubkey variant uses tuple([bytes]) for SmallVec<u8, u8>
    content = content.replace(/beet\.tuple\(\[beet\.bytes\]\)/g, 'beet.tuple([smallArray(beet.u8, beet.u8)])');
    content = content.replace(/Pubkey: \{ fields: \[Uint8Array\] \}/g, 'Pubkey: { fields: [number[]] }');
  }

  if (fileName === 'SmartAccountCompiledInstruction.ts') {
    content = content.replace(
      /\['accountIndexes', smallArray\(beet\.u8, beet\.u8\)\]/g,
      "['accountIndexes', beet.bytes]"
    );
    content = content.replace(
      /\['data', smallArray\(beet\.u16, beet\.u8\)\]/g,
      "['data', beet.bytes]"
    );
    content = content.replace(/accountIndexes: number\[]/g, 'accountIndexes: Uint8Array');
    content = content.replace(/data: number\[]/g, 'data: Uint8Array');
  }

  if (fileName === 'SmartAccountMessageAddressTableLookup.ts') {
    content = content.replace(
      /\['writableIndexes', smallArray\(beet\.u8, beet\.u8\)\]/g,
      "['writableIndexes', beet.bytes]"
    );
    content = content.replace(
      /\['readonlyIndexes', smallArray\(beet\.u8, beet\.u8\)\]/g,
      "['readonlyIndexes', beet.bytes]"
    );
    content = content.replace(/writableIndexes: number\[]/g, 'writableIndexes: Uint8Array');
    content = content.replace(/readonlyIndexes: number\[]/g, 'readonlyIndexes: Uint8Array');
  }

  // Add smallArray import if file was modified
  if (content !== originalContent) {
    const usesSmallArray = content.includes('smallArray(');

    if (!usesSmallArray) {
      content = content.replace(/import \{ smallArray \} from '\.\.\/\.\.\/types'\n/g, '');
    }

    if (usesSmallArray && !content.includes("import { smallArray }") && !content.includes("{ smallArray }")) {
      content = content.replace(
        /import \* as beet from '@metaplex-foundation\/beet'/,
        `import * as beet from '@metaplex-foundation/beet'\nimport { smallArray } from '../../types'`
      );
    }

    fs.writeFileSync(filePath, content);
    console.log(`Fixed SmallVec serialization in ${fileName}`);
    return true;
  }

  return false;
}

function main() {
  console.log('Post-processing solita-generated files for SmallVec...\n');

  let filesFixed = 0;

  if (fs.existsSync(GENERATED_DIR)) {
    const files = fs.readdirSync(GENERATED_DIR).filter(f => f.endsWith('.ts'));

    for (const file of files) {
      const filePath = path.join(GENERATED_DIR, file);
      if (processFile(filePath)) {
        filesFixed++;
      }
    }
  }

  console.log(`\nDone! Fixed ${filesFixed} file(s).`);
}

main();
